<script setup lang="ts">
import OfficialAccountMenu from '~/components/tenant/OfficialAccountMenu.vue'
import OfficialAccountReplies from '~/components/tenant/OfficialAccountReplies.vue'
import OfficialAccountTemplates from '~/components/tenant/OfficialAccountTemplates.vue'
import {dateTime} from '~/utils/update-center'
import type {OfficialConfig as Config} from '~/types/official-account'
import ConsoleDiscardChangesDialog from '~/components/console/ConsoleDiscardChangesDialog.vue'
const discard=useDiscardChanges(()=>!!busy.value||imageBusy.value)
import MaterialPicker from '../../components/console/MaterialPicker.vue'
import ImageViewer from '../../components/console/ImageViewer.vue'
import ImageSelectTile from '../../components/console/ImageSelectTile.vue'
import ConsoleValidatedForm from '../../components/console/ConsoleValidatedForm.vue'
import AdminConsole from '../../components/console/AdminConsole.vue'
import ConsoleSettingsActions from '../../components/console/ConsoleSettingsActions.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
definePageMeta({layout:'tenant',key:route=>route.path})
type View={applicationKey:string|null;applications:{key:string;name:string}[];version:number;config:Config;hasAppSecret:boolean;hasToken:boolean;hasEncodingAESKey:boolean;domains:{business:string;message:string};callbackUrl:string;menuPayload:unknown;tasks:{id:string;kind:string;status:string;errorCode:string|null;createdAt:string;settingsVersion:number}[];canWrite:boolean}
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/official-account',toast=useToast()
const initialApplication=typeof useRoute().query.application==='string'?String(useRoute().query.application):''
const initial=await useAsyncData<View>('tenant-official-account:'+auth.session.value?.id+':'+tenantId+':'+initialApplication,(_nuxt,{signal})=>auth.api<View>(endpoint+(initialApplication?'?applicationKey='+encodeURIComponent(initialApplication):''),'GET',undefined,{signal}))
if(initial.error.value&&!auth.session.value)await navigateTo('/admin/login',{replace:true})
const data=ref<View|null>(initial.data.value??null),applicationKey=ref(data.value?.applicationKey||''),form=ref<Config|null>(data.value?structuredClone(toRaw(data.value.config)):null),baseline=ref(JSON.stringify(form.value)),appSecret=ref(''),clearSecret=ref(false),busy=ref<'save'|'refresh'|'retry'|'application'|'publish'|null>(null),error=ref(initial.error.value?.message||'')
const dirty=computed(()=>JSON.stringify(form.value)!==baseline.value||!!appSecret.value||clearSecret.value||!!token.value||!!encodingAESKey.value||clearToken.value||clearEncodingAESKey.value),locked=computed(()=>!!busy.value||!data.value?.canWrite)
const publishOpen=ref(false),taskLabels:Record<string,string>={PENDING:'待处理',PREPARING:'准备中',SENDING:'提交中',ACCEPTED:'微信已受理',FAILED:'处理失败',UNKNOWN:'结果待核对'}
const qrPreview=ref(false),savedQr=computed(()=>data.value?.config.qrMaterialId?'/api/v1'+materialEndpoint+'/'+data.value.config.qrMaterialId+'/content':null)
const section=useRouteTab<string>('access',['access','menu','templates','replies']),configurationOpen=ref(false),token=ref(''),encodingAESKey=ref(''),clearToken=ref(false),clearEncodingAESKey=ref(false),copying=ref('')
const imageOpen=ref(false),imageBusy=ref(false),materialEndpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/shared'
const controller=new AbortController();let disposed=false
function fill(value:View){data.value=value;applicationKey.value=value.applicationKey||'';form.value=structuredClone(toRaw(value.config));baseline.value=JSON.stringify(form.value);appSecret.value='';clearSecret.value=false;token.value='';encodingAESKey.value='';clearToken.value=false;clearEncodingAESKey.value=false}
function cancel(){if(busy.value||imageBusy.value)return;form.value=JSON.parse(baseline.value);appSecret.value='';clearSecret.value=false;token.value='';encodingAESKey.value='';clearToken.value=false;clearEncodingAESKey.value=false;error.value='';discard.keep()}
async function refresh(source:'refresh'|'retry'|'application'='refresh',key=applicationKey.value){if(busy.value||imageBusy.value)return;if(dirty.value){discard.request(()=>{cancel();void refresh(source,key)});return}busy.value=source;error.value='';try{const result=await auth.api<View>(endpoint+(key?'?applicationKey='+encodeURIComponent(key):''),'GET',undefined,{signal:controller.signal});if(!disposed)fill(result)}catch(e:any){if(!disposed)error.value=e.message||'公众号配置读取失败'}finally{if(!disposed)busy.value=null}}
function chooseApplication(value:string){if(value!==applicationKey.value)void refresh('application',value)}
async function save(){if(imageBusy.value||locked.value||!dirty.value||!form.value||!data.value||!applicationKey.value)return;busy.value='save';error.value='';try{const result=await auth.api<View>(endpoint+'/'+encodeURIComponent(applicationKey.value),'PUT',{version:data.value.version,config:{...form.value},appSecret:appSecret.value,clearSecret:clearSecret.value,token:token.value,encodingAESKey:encodingAESKey.value,clearToken:clearToken.value,clearEncodingAESKey:clearEncodingAESKey.value},{signal:controller.signal});if(!disposed){fill(result);toast.add({title:'公众号配置已保存',color:'success'})}}catch(e:any){if(!disposed)error.value=e.message||'保存失败'}finally{if(!disposed)busy.value=null}}
async function publishMenu(){if(busy.value||dirty.value||!data.value?.canWrite)return;busy.value='publish';error.value='';try{const value=await auth.api<View>(endpoint+'/'+encodeURIComponent(applicationKey.value)+'/publish-menu','POST',{version:data.value.version},{signal:controller.signal});if(!disposed){fill(value);publishOpen.value=false;toast.add({title:'菜单发布已提交，请稍后刷新查看结果',color:'success'})}}catch(e:any){if(!disposed)error.value=e.message}finally{if(!disposed)busy.value=null}}
async function copy(key:string,value:string){if(copying.value||!value)return;copying.value=key;try{await navigator.clipboard.writeText(value);toast.add({title:'已复制',color:'success'})}catch{error.value='复制失败，请手动复制'}finally{copying.value=''}}
onBeforeRouteLeave(to=>{if(!auth.session.value)return;if(!!busy.value||imageBusy.value){toast.add({title:'正在处理，请稍候再离开',color:'neutral'});return false}if(dirty.value){discard.request(()=>{cancel();void navigateTo(to.fullPath)});return false}})
onBeforeUnmount(()=>{disposed=true;controller.abort();appSecret.value='';token.value='';encodingAESKey.value='';busy.value=null})
</script>
<template><AdminConsole :refreshing="busy==='refresh'" @refresh="refresh()"><div class="official-page">
 <ConsolePageHeading title="微信公众号"><template #actions><USelect v-if="data&&data.applications.length>1" :model-value="applicationKey" :items="data.applications.map(app=>({value:app.key,label:app.name}))" aria-label="公众号所属应用" :disabled="!!busy" @update:model-value="chooseApplication"/></template></ConsolePageHeading>
 <div class="flex flex-wrap gap-2 border-b border-default pb-3"><UButton v-for="item in [{key:'access',label:'接入流程'},{key:'menu',label:'自定义菜单'},{key:'templates',label:'模板消息'},{key:'replies',label:'自动回复'}]" :key="item.key" type="button" :color="section===item.key?'primary':'neutral'" :variant="section===item.key?'soft':'ghost'" :disabled="!!busy||imageBusy" @click="section=item.key">{{item.label}}</UButton></div>
 <UAlert v-if="error" color="error" :title="error"><template v-if="!data" #actions><UButton :loading="busy==='retry'" @click="refresh('retry')">重试</UButton></template></UAlert>
 <ConsoleValidatedForm v-if="form&&data?.applicationKey" class="official-stack" @submit="save" @invalid="error=$event"><section v-if="section==='access'&&!configurationOpen" class="surface-card official-content grid gap-8 p-5 sm:p-7 lg:grid-cols-[1fr_15rem]"><ol class="official-steps"><li><h2 class="text-sm font-semibold">公众号认证</h2><p class="my-3 text-sm text-muted">在微信公众平台完成注册、主体认证，并确认所需接口权限。</p><UButton type="button" to="https://mp.weixin.qq.com" target="_blank" color="neutral" variant="outline" icon="i-lucide-external-link">打开微信公众平台</UButton></li><li><h2 class="text-sm font-semibold">配置公众号</h2><p class="my-3 text-sm text-muted">填写公众号资料和开发者凭据，再配置消息接收与域名。</p><UButton type="button" @click="configurationOpen=true">配置微信公众号</UButton></li><li><h2 class="text-sm font-semibold">验证与发布</h2><p class="mt-3 text-sm text-muted">将回调地址、Token 和消息加密配置填入微信公众平台；验证通过后，再发布菜单并检查自动回复。</p><p class="mt-2 text-xs text-muted">发布前请核对公众号身份、认证状态及接口权限。</p></li></ol><div class="official-qr space-y-3 text-center"><button v-if="savedQr" type="button" class="rounded-md focus-visible:ring-2 focus-visible:ring-primary" aria-label="查看公众号二维码" @click="qrPreview=true"><img :src="savedQr" alt="公众号二维码" class="size-40 object-contain"/></button><div v-else class="flex size-40 flex-col items-center justify-center gap-3 rounded-md bg-elevated text-muted"><UIcon name="i-lucide-message-circle" class="size-8"/><span class="text-xs">尚未配置二维码</span></div><p class="text-sm">{{data.config.displayName||'尚未配置公众号名称'}}</p><p class="text-xs text-muted">{{savedQr?'扫码进入本公众号':'请在公众号设置中填写'}}</p></div></section><template v-if="section==='access'&&configurationOpen"><UButton type="button" class="self-start" color="neutral" variant="ghost" icon="i-lucide-chevron-left" @click="configurationOpen=false">返回接入流程</UButton><section class="surface-card official-form space-y-6 p-5 sm:p-7"><h2 class="text-base font-semibold">公众号基础信息</h2>
  <ConsoleSettingsField label="公众号名称" input-id="official-name"><ConsoleInput id="official-name" v-model="form.displayName" :maxlength="32" :disabled="locked" placeholder="请输入公众号名称"/></ConsoleSettingsField>
  <ConsoleSettingsField label="公众号类型" input-id="official-type"><USelect id="official-type" v-model="form.accountType" class="w-full" :items="[{label:'服务号',value:'service'},{label:'订阅号',value:'subscription'}]" :disabled="locked"/></ConsoleSettingsField>
  <ConsoleSettingsField label="原始 ID" input-id="official-original-id"><ConsoleInput id="official-original-id" v-model="form.originalId" :maxlength="64" :disabled="locked" placeholder="gh_ 开头，选填"/></ConsoleSettingsField>
  <ConsoleSettingsField label="公众号二维码"><ImageSelectTile :src="form.qrMaterialId?'/api/v1'+materialEndpoint+'/'+form.qrMaterialId+'/content':null" label="公众号二维码" fit="contain" :disabled="locked||imageBusy" :removable="!!form.qrMaterialId" @select="imageOpen=true" @remove="form.qrMaterialId=null"/><p class="mt-2 text-xs text-muted">建议使用 400 × 400px 图片，从本站素材库上传或选择。移除只解除关联。</p></ConsoleSettingsField>
 </section><section class="surface-card official-form space-y-6 p-5 sm:p-7"><h2 class="text-base font-semibold">开发者配置</h2><p class="text-xs text-muted">{{data.hasAppSecret&&data.config.appId?'公众号凭据已配置':'请填写 AppID 和 AppSecret，保存后即可调用'}}</p>
  <ConsoleSettingsField label="AppID" input-id="official-app-id"><ConsoleInput id="official-app-id" v-model="form.appId" :maxlength="18"  :disabled="locked" autocomplete="off" placeholder="wx 开头的微信公众号 AppID"/></ConsoleSettingsField>
  <ConsoleSettingsField label="AppSecret" input-id="official-app-secret"><ConsoleInput id="official-app-secret" v-model="appSecret" type="password" autocomplete="new-password" :maxlength="32" :disabled="locked||clearSecret" :placeholder="data.hasAppSecret?'已保存，留空保留；填写新值可替换':'请输入 32 位 AppSecret'"/><p class="mt-2 text-xs text-muted">密钥加密保存，不回显。更换 AppID 后须重新填写对应密钥。</p><UCheckbox v-if="data.hasAppSecret" v-model="clearSecret" class="mt-3" label="清除已保存的 AppSecret" :disabled="locked||!!appSecret"/></ConsoleSettingsField>
 </section><section class="surface-card official-form space-y-6 p-5 sm:p-7"><h2 class="text-base font-semibold">消息推送配置</h2><p class="text-xs text-muted">填写原始 ID、Token 及所选模式的加密密钥后自动接收消息；无需额外开启。</p>
 <ConsoleSettingsField label="服务器地址"><div class="flex min-w-0 gap-3"><ConsoleInput :model-value="data.callbackUrl" readonly class="min-w-0 flex-1" aria-label="服务器地址"/><UButton type="button" class="shrink-0 whitespace-nowrap" color="neutral" variant="outline" icon="i-lucide-copy" :loading="copying==='callback'" @click="copy('callback',data.callbackUrl)">复制</UButton></div></ConsoleSettingsField>
 <ConsoleSettingsField label="Token" input-id="official-token"><ConsoleInput id="official-token" v-model="token" type="password" autocomplete="new-password" pattern="[A-Za-z0-9]{3,32}" :maxlength="32" :disabled="locked||clearToken" :placeholder="data.hasToken?'已保存，留空保留':'3–32 位英文字母或数字'"/><UCheckbox v-if="data.hasToken" v-model="clearToken" class="mt-3" label="清除 Token" :disabled="locked||!!token"/></ConsoleSettingsField>
 <ConsoleSettingsField label="EncodingAESKey" input-id="official-aes"><ConsoleInput id="official-aes" v-model="encodingAESKey" type="password" autocomplete="new-password" pattern="[A-Za-z0-9+/]{43}" :maxlength="43" :disabled="locked||clearEncodingAESKey" :placeholder="data.hasEncodingAESKey?'已保存，留空保留':'微信公众平台生成的 43 位消息加密密钥'"/><UCheckbox v-if="data.hasEncodingAESKey" v-model="clearEncodingAESKey" class="mt-3" label="清除消息加密密钥" :disabled="locked||!!encodingAESKey"/></ConsoleSettingsField>
 <ConsoleSettingsField label="消息加解密方式" input-id="official-mode"><USelect id="official-mode" v-model="form.messageMode" :disabled="locked" :items="[{label:'明文模式',value:'plain'},{label:'兼容模式',value:'compatible'},{label:'安全模式（推荐）',value:'safe'}]"/><p class="mt-2 text-xs text-muted">需与微信公众平台保持一致。兼容和安全模式须配置 EncodingAESKey。</p></ConsoleSettingsField>
 </section><section class="surface-card official-form space-y-6 p-5 sm:p-7"><h2 class="text-base font-semibold">功能设置</h2><ConsoleSettingsField v-for="label in ['业务域名','JS 接口安全域名','网页授权域名']" :key="label" :label="label"><div class="flex min-w-0 gap-3"><ConsoleInput :model-value="data.domains?.business||''" readonly class="min-w-0 flex-1" :aria-label="label"/><UButton type="button" class="shrink-0 whitespace-nowrap" color="neutral" variant="outline" icon="i-lucide-copy" :loading="copying===label" :disabled="!data.domains?.business" @click="copy(label,data.domains.business)">复制</UButton></div></ConsoleSettingsField><p class="text-xs text-muted">域名来自当前部署配置。需在微信公众平台完成校验；域名展示不表示网页授权或 JS 接口已经开通。</p></section></template>
 <OfficialAccountMenu v-if="section==='menu'" v-model="form.menu" :disabled="locked"/>
 <OfficialAccountTemplates v-if="section==='templates'" v-model="form.templates" :disabled="locked"/><OfficialAccountReplies v-if="section==='replies'" v-model="form.replies" :disabled="locked" @busy="imageBusy=$event"/>
 <ConsoleSettingsActions v-if="section!=='access'||configurationOpen" :dirty="dirty" :busy="!!busy||imageBusy" :saving="busy==='save'" :can-write="data.canWrite" :save-disabled="imageBusy" @cancel="discard.request(cancel)"><template #before><template v-if="section==='menu'"><UButton type="button" icon="i-lucide-upload" :loading="busy==='publish'" :disabled="!!busy||dirty||!form.menu.length||!data.hasAppSecret" @click="publishOpen=true">发布菜单到微信</UButton></template></template></ConsoleSettingsActions></ConsoleValidatedForm>
 <section v-if="data?.tasks?.length" class="surface-card p-5 sm:p-7"><h2 class="mb-4 text-sm font-semibold">最近处理记录</h2><div v-for="task in data.tasks" :key="task.id" class="flex flex-wrap justify-between gap-3 border-t border-default py-3 text-sm"><span>{{task.kind==='menu'?'菜单发布':'自动回复'}}</span><span>{{taskLabels[task.status]||task.status}}</span><span class="text-muted">{{dateTime(task.createdAt)}}</span><span v-if="task.status==='UNKNOWN'" class="text-warning">请先到微信后台核对，系统不会重复发送</span></div></section>
 <UModal v-model:open="publishOpen" title="发布公众号菜单" description="将已保存的菜单更新到当前公众号。请确认内容及公众号身份。" :dismissible="!busy" :close="!busy"><template #body><p class="text-sm">公众号：{{data?.config.displayName||data?.config.appId}}，配置版本 {{data?.version}}</p><UAlert v-if="error" :title="error" color="error" class="mt-4"/></template><template #footer><div class="flex w-full justify-end gap-3"><UButton color="neutral" variant="outline" :disabled="!!busy" @click="publishOpen=false">取消</UButton><UButton :loading="busy==='publish'" :disabled="!!busy" @click="publishMenu">确认发布</UButton></div></template></UModal>
 <p v-if="data&&!data.applicationKey" class="py-10 text-center text-sm text-muted">请选择要配置公众号的应用。</p>
 <ImageViewer v-model:open="qrPreview" :src="savedQr" label="公众号二维码"/>
 <MaterialPicker v-if="form" v-model:open="imageOpen" portal="tenant" :endpoint="materialEndpoint" kind="image" @busy="imageBusy=$event" @select="form.qrMaterialId=$event.id"/>
 <ConsoleDiscardChangesDialog :controller="discard"/>
</div></AdminConsole></template>
<style scoped>.official-form{--settings-label-width:11rem;--settings-content-width:36rem}.official-page :deep(.qisvc-console-page-heading){margin-block:0}.official-page,.official-stack{display:flex;flex:1;flex-direction:column;gap:1.25rem;min-width:0}.official-stack :deep(.official-content){flex:1;min-height:28rem}.official-stack :deep(.console-settings-actions){margin-top:auto}.official-steps{display:flex;flex-direction:column;align-self:stretch;counter-reset:official-step;padding-block:.5rem}.official-steps li{flex:1;position:relative;padding:0 0 2.25rem 2.75rem;counter-increment:official-step}.official-steps li:last-child{flex:0;padding-bottom:0}.official-steps li::before{content:counter(official-step);position:absolute;top:0;left:0;display:grid;place-items:center;width:1.75rem;height:1.75rem;border:1px solid var(--ui-primary);border-radius:50%;color:var(--ui-primary);background:var(--ui-bg);font-size:.8125rem;font-weight:600;z-index:1}.official-steps li:not(:last-child)::after{content:"";position:absolute;top:1.75rem;bottom:0;left:.8125rem;border-left:1px solid var(--ui-border)}.official-qr{display:flex;flex-direction:column;align-items:center;justify-content:center}.official-qr :deep(.image-select-tile){width:160px;height:160px}@media(max-width:639px){.official-stack :deep(.official-content){min-height:0}.official-steps li{flex:none;padding-bottom:1.75rem}.official-steps li:last-child{padding-bottom:0}}
</style>
